const listUserQuotas = `-- name: ListUserQuotas :many
WITH RECURSIVE ancestors AS (
    SELECT
        id child,
        id ancestor,
        parent_id,
        0 depth
    FROM
        GROUPS
    WHERE
        deleted_at IS NULL
    UNION ALL
    SELECT
        a.child,
        g.id,
        g.parent_id,
        a.depth + 1
    FROM
        ancestors a
        JOIN GROUPS g ON g.id = a.parent_id
    WHERE
        g.deleted_at IS NULL
        AND a.depth < 100
)
SELECT
    jsonb_build_object('id', u.id, 'name', u.name, 'email', u.email, 'status', u.status,
	'group_id', COALESCE(u.billing_group_id::text, $1::text)::text, 'credits',
	q.credits_per_cycle::text, 'effective_credits', COALESCE(q.credits_per_cycle, g.credits_per_cycle,
	$2::numeric)::text, 'inherited_from', CASE WHEN q.id IS NOT NULL THEN
            u.id::text
        ELSE
            COALESCE(g.ancestor::text, $1::text)::text
        END, 'external_user_id', wb.external_user_id)
FROM
    users u
    LEFT JOIN billing_quotas q ON q.user_id = u.id
        AND q.deleted_at IS NULL
    LEFT JOIN LATERAL (
        SELECT
            b.credits_per_cycle,
            a.ancestor
        FROM
            ancestors a
            JOIN billing_quotas b ON b.group_id = a.ancestor
                AND b.deleted_at IS NULL
        WHERE
            a.child = u.billing_group_id
        ORDER BY
            a.depth
        LIMIT 1) g ON TRUE
    LEFT JOIN wallet_user_bindings wb ON wb.user_id = u.id
WHERE
    u.deleted_at IS NULL
ORDER BY
    u.name,
    u.id
`

