const transactionEntries = `-- name: TransactionEntries :many
SELECT
    (to_jsonb (e) || jsonb_build_object('credit_delta', credit_delta::text, 'balance_after', balance_after::text))::jsonb
FROM
    credit_ledger_entries e
WHERE
    transaction_id = $1
ORDER BY
    SEQUENCE
`

func (q *Queries) TransactionEntries(ctx context.Context, transactionID *string) ([][]byte, error) {
	rows, err := q.db.Query(ctx, transactionEntries, transactionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := [][]byte{}
	for rows.Next() {
		var column_1 []byte
		if err := rows.Scan(&column_1); err != nil {
			return nil, err
		}
		items = append(items, column_1)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

